    return `<form class="acm-form" data-acm-form="component"><label>Draft recipe version<select name="recipe_version_id" required><option value="">Choose version</option>${optionList(versions.filter(record=>record.publication_state!=="published"),record=>`${record.recipe_name||record.recipe_id} · v${record.version_number}`)}</select></label><label>Ingredient type<select name="component_type" data-component-type><option value="formulation">Commercial product version</option><option value="pigment">Raw pigment</option><option value="recipe">Nested recipe version</option></select></label><label data-component-choice="formulation">Product formulation<select name="formulation_id"><option value="">Choose formulation</option>${optionList(formulations,record=>`${record.material_name||record.material_id} · v${record.version_number}`)}</select></label><label data-component-choice="pigment" hidden>Raw pigment<select name="raw_pigment_material_id"><option value="">Choose pigment</option>${optionList(pigments)}</select></label><label data-component-choice="recipe" hidden>Nested version<select name="nested_recipe_version_id"><option value="">Choose published version</option>${optionList(versions.filter(record=>record.publication_state==="published"),record=>`${record.recipe_name||record.recipe_id} · v${record.version_number}`)}</select></label><label>Quantity<input name="quantity_value" type="number" min="0" step="any"></label><label>Unit<select name="quantity_unit"><option>parts</option><option>drops</option><option>grams</option><option>milliliters</option><option>percent</option><option>freeform</option></select></label><label class="acm-checkbox"><input type="checkbox" name="approximate">Approximate amount</label><label class="wide">Quantity clarification<input name="quantity_note"></label><div class="acm-actions"><button class="button">Add component</button><span class="acm-output" aria-live="polite"></span></div></form>`;
