    return `<form class="acm-form" data-acm-form="profile"><label>Source type<select name="source_type" data-profile-type><option value="recipe-version">Recipe version</option><option value="material-formulation">Product formulation</option></select></label><label data-profile-source="recipe-version">Recipe version<select name="recipe_source_id">${optionList(versions,record=>`${record.recipe_name||record.recipe_id} · v${record.version_number}`)}</select></label><label data-profile-source="material-formulation" hidden>Formulation<select name="formulation_source_id">${optionList(formulations,record=>`${record.material_name||record.material_id} · v${record.version_number}`)}</select></label><label>sRGB display swatch<input name="srgb_hex" type="color" value="#777777"></label><label class="acm-checkbox wide"><input type="checkbox" name="auto_color_conversion" checked>Calculate Lab and OKLCH from sRGB</label><p class="acm-profile-help wide" data-profile-conversion-help>Lab and OKLCH are synchronized with this display swatch.</p><label>Lab L<input name="lab_l" type="number" step="any" required readonly></label><label>Lab a<input name="lab_a" type="number" step="any" required readonly></label><label>Lab b<input name="lab_b" type="number" step="any" required readonly></label><label>OKLCH L<input name="oklch_l" type="number" step="any" required readonly></label><label>OKLCH C<input name="oklch_c" type="number" step="any" required readonly></label><label>OKLCH H<input name="oklch_h" type="number" step="any" readonly></label><label>Reference method<select name="reference_method"><option value="manual-digital">Manual digital</option><option value="measured-physical">Measured physical</option><option value="reviewed-image">Reviewed image</option></select></label><div class="acm-actions"><button class="button">Save sourced color profile</button><span class="acm-output" aria-live="polite"></span></div></form>`;
