    return `<article class="acm-card"><div class="acm-meta"><span class="acm-pill">${esc(title(product.material_kind))}</span><span>${published?"Published in Archive":"Studio draft"}</span></div><div class="acm-profile-summary"><span class="acm-swatch" style="--swatch:${esc(product.srgb_hex||"#777777")}"></span><h4>${esc(product.name)}</h4></div>${detailRows([["Brand",product.brand],["Product line",product.product_line],["Color name",product.color_name],["Product code",product.product_code],["Finish",title(product.normalized_finish)],["Opacity",title(product.opacity)]])}<section class="acm-declarations"><h5>Manufacturer-listed pigments</h5>${listed.length?listed.map(item=>`<article class="acm-declaration"><strong>${esc(item.pigment_name||item.normalized_pigment_code)}</strong><p>${esc(item.bottle_wording)}</p><div class="acm-meta"><span>${esc(title(item.source_type))}</span><span>${esc(item.observed_at||"Undated")}</span></div>${!published?declarationEditForm(item,pigments):""}</article>`).join(""):"<p>No manufacturer-listed pigments recorded yet.</p>"}${pigmentEvidenceForm(product,pigments)}</section>${published?'<p class="acm-lock-note">Published product identity is locked. You can still append newly observed manufacturer pigment evidence; archive and replace the product only if its identity or formula changes.</p>':productEditForm(product)}</article>`;
