      mount.querySelector("[data-map-save]").addEventListener("click",async()=>{try{if(regions.some(region=>!region.color_usage_id))throw new Error("Assign every region to a color usage.");await post(api,`/api/admin/archive-dossiers/${encodeURIComponent(selectedStateId)}/palette-materials/regions-sync`,"POST",{map_id:map.id,regions});await post(api,`/api/admin/archive-dossiers/${encodeURIComponent(selectedStateId)}/palette-materials/maps/${encodeURIComponent(map.id)}`,"PATCH",{overlay_opacity:Number(mount.querySelector("[data-map-opacity]").value)});output.textContent="Reviewed geometry saved.";status("Palette map geometry saved");await loadState()}catch(error){output.textContent=error.message}});
